events.command:
/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p\\n' | sort && printf '\\nTOOLS\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
mods=['cv2','PIL','numpy','scipy','imageio','torch']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',e)
PY"

/bin/bash -lc 'for x in ffmpeg python3; do command -v "$x" || true; done; python3 - <<'"'PY'
mods=['cv2','PIL','numpy','scipy','imageio','torch']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',type(e).__name__,e)
PY"
